script:
// Verified through the Cypress layer (ui/cypress/e2e/v16/05-customisations.cy.js).
// The HTTP engine cannot run browser JS, so this script's only proof of life is
// the button and the indicator appearing on a real form.
frappe.ui.form.on("Sales Invoice", {
	refresh(frm) {
		frm.add_custom_button("RT Release Check", () => {
			frm.set_value("rt_release_ref", "RT-CLIENT-" + (frm.doc.customer || "NA"));
			frappe.show_alert({ message: "RT client script ran", indicator: "green" });
		});
		frm.page.set_indicator("RT customised", "blue");
	},
});
